var payload = msg.payload;

// Detect SignalK hello / reconnect → re-subscribe
if (payload && payload.version && payload.self) {
    var subMsg = {
        payload: JSON.stringify({
            context: 'vessels.self',
            subscribe: [{path: 'notifications.*', minPeriod: 1000}]
        })
    };
    return [subMsg, null];
}

// Extract notification path/state from delta updates
var msgs = [];
var updates = payload.updates || [];
for (var i = 0; i < updates.length; i++) {
    var ts = updates[i].timestamp || new Date().toISOString();
    var values = updates[i].values || [];
    for (var j = 0; j < values.length; j++) {
        var entry = values[j];
        var path = entry.path || '';
        var value = entry.value;
        if (typeof path === 'string' && path.startsWith('notifications.') &&
                value && typeof value === 'object') {
            msgs.push({
                topic: path,
                payload: {
                    path: path.replace(/^notifications\./, ''),
                    state: (value.state || 'normal'),
                    message: (value.message || path),
                    timestamp: ts
                }
            });
        }
    }
}
return [null, msgs.length > 0 ? msgs : null];

var path    = msg.payload.path;
var state   = msg.payload.state;
var message = msg.payload.message || path;
var ts      = msg.payload.timestamp;

// Maintain active-alert map in flow context (RAM only)
var activeAlerts = context.get('activeAlerts') || {};
if (state === 'alarm' || state === 'emergency') {
    activeAlerts[path] = {state: state, message: message, since: ts};
    node.warn('ALERT active: ' + path + ' [' + state + '] ' + message);
} else if (state === 'normal') {
    if (activeAlerts[path]) {
        node.warn('ALERT cleared: ' + path);
    }
    delete activeAlerts[path];
}
context.set('activeAlerts', activeAlerts);

// JSON event for vxt-orchestrator
var outMsg = {
    payload: JSON.stringify({
        path: path,
        state: state,
        value: {message: message},
        timestamp: ts
    })
};

// Trigger immediate TTS only on alarm/emergency
if (state === 'alarm' || state === 'emergency') {
    return [outMsg, {payload: message}];
}
return [outMsg, null];

// Strip shell-unsafe characters; espeak-ng receives plain unquoted text
var text = String(msg.payload || '')
    .replace(/["'\\;|&$`<>!\n\r]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 200);
if (!text) return null;
msg.payload = text;
return msg;

// Repeat TTS for every currently-active alert
var activeAlerts = context.get('activeAlerts') || {};
var keys = Object.keys(activeAlerts);
if (keys.length === 0) return null;

var msgs = [];
for (var k = 0; k < keys.length; k++) {
    msgs.push({payload: activeAlerts[keys[k]].message});
}
return [msgs];
